let metrics = {
    rules_processed: 0,
    alerts_created: 0,
    alerts_skipped: 0,
    emails_queued: 0,
    emails_sent: 0,
    sms_sent: 0,
    errors_count: 0,
    error_details: [],
    execution_log_summary: []
};

const items = Array.isArray($input.all()) ? $input.all() : [$input.all()];
metrics.rules_processed = items.length;

for (const item of items) {
    const data = item.json;

    if (data.success === false) {
        metrics.errors_count++;
        const detail = data.error || (data.error_details ? JSON.stringify(data.error_details) : 'Sin detalle');
        metrics.error_details.push(`Error en ejecución: ${detail}`);
        continue;
    }

    metrics.emails_sent += Number(data.emails_sent) || 0;

    if (data.execution_log && Array.isArray(data.execution_log)) {
        for (const log of data.execution_log) {
            if (Object.keys(log).length === 0) {
                metrics.alerts_skipped++;
                continue;
            }

            if (log.id) {
                metrics.alerts_created++;

                if (log.status === "PENDING") {
                    if (log.details_json?.patient?.email && log.details_json.patient.email !== "null") {
                        metrics.emails_queued++;
                    }
                }

                // Estimate only (mirrors emails_queued): counts alerts whose patient has a phone,
                // not confirmed WhatsApp deliveries. The authoritative record of what was actually
                // sent/failed lives in alert_actions (SEND_WHATSAPP rows written by the
                // "Alert WhatsApp Auto-Send" sub-workflow), surfaced in alerts/page.tsx.
                if (log.details_json?.patient?.phone) metrics.sms_sent++;

                metrics.execution_log_summary.push({
                    id: log.id,
                    rule_id: log.rule_id,
                    title: log.title,
                    status: log.status,
                    patient: log.details_json?.patient?.full_name || "N/A"
                });
            } else {
                metrics.alerts_skipped++;
            }
        }
    }
}

return [{
    json: metrics
}];

const results = [];
const target_date = $("When Executed by Another Workflow").first().json
  .target_date;

// El origen de una regla puede ser una tabla o una vista "v_alert_*". Todo lo
// que se interpola como identificador se valida para no inyectar SQL.
const IDENT = /^[a-z_][a-z0-9_]*$/;
const ident = (name, what) => {
  if (typeof name !== "string" || !IDENT.test(name)) {
    throw new Error(`Alert rule: invalid ${what} "${name}"`);
  }
  return name;
};
const lit = (v) => `'${String(v ?? "").replace(/'/g, "''")}'`;

// Variables de fecha que identifican la fecha del evento en una condicion "=".
const DATE_VAR =
  /^\{\{\s*(TODAY|TOMORROW|YESTERDAY|WEEK_START|WEEK_END|MONTH_START|MONTH_END|YEAR_START|YEAR_END)/i;

for (const item of items) {
  const rule = item.json;

  const ruleId = Number(rule.id);
  if (!Number.isInteger(ruleId)) {
    throw new Error(`Alert rule: invalid id "${rule.id}"`);
  }

  const conditionConfig = rule.condition_config || {};
  const conditions = conditionConfig.conditions || [];
  const userIdField =
    conditionConfig.user_id_field !== undefined &&
    conditionConfig.user_id_field !== null &&
    conditionConfig.user_id_field !== ""
      ? ident(conditionConfig.user_id_field, "user_id_field")
      : null;

  const sourceTable = ident(rule.source_table, "source_table");
  // Con una vista, las alert_instances siguen apuntando a la tabla real
  // (reference_table/reference_id): el envio de WhatsApp resuelve la entidad
  // por reference_table y el anti-duplicado tambien la usa. El frontend guarda
  // condition_config.reference_table al elegir la vista (sale del COMMENT de
  // la vista via GET /system/tables). Sin ese dato se usa el propio origen.
  const referenceTable = ident(
    conditionConfig.reference_table || sourceTable,
    "reference_table",
  );

  const daysBefore = Math.max(0, Number(rule.days_before) || 0);
  const daysAfter = Math.max(0, Number(rule.days_after) || 0);

  const dateOffsetSql = ` + INTERVAL '${daysBefore} days' - INTERVAL '${daysAfter} days'`;

  const whereClauses = conditions.map((c, index) => {
    const column = ident(c.column, "condition column");
    let val = c.value;

    if (typeof val === "string" && val.includes("{{") && val.includes("}}")) {
      const cleanVar = val.replace(/[{}\s]/g, "").toUpperCase();

      const dateMappings = {
        TODAY_NO_YEAR: `TO_CHAR('${target_date}'::date${dateOffsetSql}, 'MM-DD')`,
        TODAY: `('${target_date}'::date${dateOffsetSql})::date`,
        TOMORROW: `('${target_date}'::date + INTERVAL '1 day'${dateOffsetSql})::date`,
        YESTERDAY: `('${target_date}'::date - INTERVAL '1 day'${dateOffsetSql})::date`,
        WEEK_START: `(DATE_TRUNC('week', '${target_date}'::date)${dateOffsetSql})::date`,
        WEEK_END: `(DATE_TRUNC('week', '${target_date}'::date) + INTERVAL '6 days'${dateOffsetSql})::date`,
        DOW: `EXTRACT(DOW FROM '${target_date}'::date${dateOffsetSql})`,
        MONTH_START: `(DATE_TRUNC('month', '${target_date}'::date)${dateOffsetSql})::date`,
        MONTH_END: `(DATE_TRUNC('month', '${target_date}'::date) + INTERVAL '1 month - 1 day'${dateOffsetSql})::date`,
        YEAR_START: `(DATE_TRUNC('year', '${target_date}'::date)${dateOffsetSql})::date`,
        YEAR_END: `(DATE_TRUNC('year', '${target_date}'::date) + INTERVAL '1 year - 1 day'${dateOffsetSql})::date`,
      };

      const baseKey = Object.keys(dateMappings).find((key) =>
        cleanVar.startsWith(key),
      );

      if (baseKey) {
        let baseSql = dateMappings[baseKey];
        const arithmetic = cleanVar.replace(baseKey, "");

        if (arithmetic) {
          val = `(${baseSql} ${arithmetic})`;
        } else {
          val = baseSql;
        }
      }
    } else if (typeof val === "string") {
      val = lit(val);
    }

    const columnSql = String(val).includes("MM-DD")
      ? `TO_CHAR(t.${column}, 'MM-DD')`
      : `t.${column}`;

    let clause = "";
    const operator = String(c.operator || "").toUpperCase();
    if (operator === "BETWEEN") {
      // days_before / days_after son offsets respecto al EVENTO, no una ventana
      // que siempre incluye el dia de hoy:
      //   days_before = N -> el evento ocurre N dias despues del target
      //   days_after  = N -> el evento ocurrio N dias antes del target
      // Si ambos son > 0 el rango cubre la ventana completa entre ambos extremos
      // (ej. facturas a vencer dentro de +/- 5 dias). Si solo uno esta seteado,
      // apunta a ese dia exacto (ej. recordatorio 24h: 1 y 0 -> solo manana).
      let startOffset;
      let endOffset;
      if (daysBefore > 0 && daysAfter > 0) {
        startOffset = -daysAfter;
        endOffset = daysBefore + 1;
      } else if (daysBefore > 0) {
        startOffset = daysBefore;
        endOffset = daysBefore + 1;
      } else if (daysAfter > 0) {
        startOffset = -daysAfter;
        endOffset = -daysAfter + 1;
      } else {
        startOffset = 0;
        endOffset = 1;
      }
      const startRange = `('${target_date}'::date + INTERVAL '${startOffset} days')`;
      const endRange = `('${target_date}'::date + INTERVAL '${endOffset} days')`;
      clause = `${columnSql} >= ${startRange} AND ${columnSql} < ${endRange}`;
    } else if (operator === "IS NULL" || operator === "IS NOT NULL") {
      clause = `${columnSql} ${operator}`;
    } else {
      clause = `${columnSql} ${c.operator} ${val}`;
    }

    const logic = index === 0 ? "" : c.logic || "";
    return `${logic} ${clause}`.trim();
  });

  const shouldJoinUser = userIdField !== null;
  const u = shouldJoinUser ? "u" : "t";

  const userJoinClause = shouldJoinUser
    ? `LEFT JOIN public.users u ON t.${userIdField} = u.id`
    : "";

  const finalUserId = shouldJoinUser ? `t.${userIdField}` : "t.id";

  // Telefono de contacto: el del paciente o, si es dependiente sin telefono
  // propio, el de su responsable. Snapshot sin normalizar: el envio de
  // WhatsApp normaliza (Uruguay) y valida el numero por su cuenta.
  // Solo cuando "u" es la tabla users (join por user_id_field u origen users).
  const canResolveResponsible = shouldJoinUser || sourceTable === "users";
  const responsibleJoinClause = canResolveResponsible
    ? `LEFT JOIN public.users r ON r.id = ${u}.responsible_contact_id`
    : "";
  const phoneSql = canResolveResponsible
    ? `COALESCE(NULLIF(${u}.phone_number, ''), CASE WHEN ${u}.is_dependant THEN NULLIF(r.phone_number, '') END)`
    : `${u}.phone_number`;
  const phoneFromResponsibleSql = canResolveResponsible
    ? `(NULLIF(${u}.phone_number, '') IS NULL AND ${u}.is_dependant AND NULLIF(r.phone_number, '') IS NOT NULL)`
    : "false";
  const responsibleNameSql = canResolveResponsible ? "r.name" : "NULL";

  // Anti-duplicado por OCURRENCIA (script 136): una alerta por regla +
  // registro + fecha del evento, sin importar su estado. Si la fecha del
  // evento cambia (cita reprogramada, vencimiento extendido, cumpleaños
  // corregido) es otra ocurrencia y se crea una alerta nueva.
  // La fecha del evento es condition_config.event_field: una columna, "none"
  // (sin fecha) o vacio = se deduce de las condiciones (primer BETWEEN o, si
  // no hay, el primer "=" contra una variable de fecha). Modos:
  //   event  -> occurrence_key = valor de la columna (to_jsonb, mismo formato
  //             que el snapshot details_json.data).
  //   yearly -> la condicion sobre la columna usa {{TODAY_NO_YEAR}}
  //             (cumpleaños): occurrence_key = dia de la ocurrencia este año.
  //   state  -> sin fecha de evento: occurrence_key = alert_date y no se
  //             re-crea mientras exista una alerta ABIERTA para el registro.
  const eventFieldConfig = conditionConfig.event_field;
  let eventField = null;
  if (eventFieldConfig && eventFieldConfig !== "none") {
    eventField = ident(eventFieldConfig, "event_field");
  } else if (!eventFieldConfig) {
    const anchor =
      conditions.find(
        (c) => String(c.operator || "").toUpperCase() === "BETWEEN",
      ) ||
      conditions.find(
        (c) =>
          c.operator === "=" &&
          typeof c.value === "string" &&
          DATE_VAR.test(c.value.trim()),
      );
    eventField = anchor ? ident(anchor.column, "event_field") : null;
  }

  const isYearlyEvent =
    eventField !== null &&
    conditions.some(
      (c) =>
        c.column === eventField &&
        typeof c.value === "string" &&
        /TODAY_NO_YEAR/i.test(c.value),
    );
  const occurrenceMode =
    eventField === null ? "state" : isYearlyEvent ? "yearly" : "event";

  const matchedDaySql = `('${target_date}'::date${dateOffsetSql})::date`;
  const eventValueSql = `(to_jsonb(t.*)->>'${eventField}')`;
  let occurrenceKeySql;
  let eventDateSql;
  if (occurrenceMode === "event") {
    occurrenceKeySql = `COALESCE(${eventValueSql}, 'null')`;
    eventDateSql = `CASE WHEN pg_input_is_valid(${eventValueSql}, 'timestamp') THEN ${eventValueSql}::timestamp END`;
  } else if (occurrenceMode === "yearly") {
    occurrenceKeySql = `TO_CHAR(${matchedDaySql}, 'YYYY-MM-DD')`;
    eventDateSql = `${matchedDaySql}::timestamp`;
  } else {
    occurrenceKeySql = `TO_CHAR('${target_date}'::date, 'YYYY-MM-DD')`;
    eventDateSql = "NULL::timestamp";
  }

  const dedupExtraClause =
    occurrenceMode === "state"
      ? `AND (ai.occurrence_key = ${occurrenceKeySql} OR ai.status NOT IN ('COMPLETED', 'ACTION_TAKEN', 'IGNORED', 'SUPPRESSED', 'SNOOZED'))`
      : `AND ai.occurrence_key = ${occurrenceKeySql}`;

  const duplicatePrevention = `NOT EXISTS (
    SELECT 1 FROM public.alert_instances ai
    WHERE ai.rule_id = ${ruleId}
      AND ai.reference_table = '${referenceTable}'
      AND ai.reference_id = t.id::text
      ${dedupExtraClause}
  )`;

  const whereSql =
    whereClauses.length > 0
      ? `WHERE (${whereClauses.join(" ")}) AND ${duplicatePrevention}`
      : `WHERE ${duplicatePrevention}`;

  const dynamicQuery = `
    SELECT
      ${lit(rule.id)} as rule_id,
      '${referenceTable}' as reference_table,
      t.id as reference_id,
      ${finalUserId} as user_id,
      CAST('${target_date}' AS DATE) as alert_date,
      ${occurrenceKeySql} as occurrence_key,
      ${eventDateSql} as event_date,
      '${occurrenceMode}' as occurrence_mode,
      ${lit(rule.name)} as title,
      ${lit(rule.priority)} as priority,
      ${lit(rule.description)} as description,
      jsonb_build_object(
        'data', to_jsonb(t.*),
        'patient', jsonb_build_object(
          'full_name', ${u}.name,
          'email', ${u}.email,
          'phone', ${phoneSql},
          'phone_from_responsible', ${phoneFromResponsibleSql},
          'responsible_name', ${responsibleNameSql},
          'document_id', ${u}.identity_document
        ),
        'clinic', jsonb_build_object(
          'name', c.name,
          'address', c.address,
          'phone', c.phone,
          'email', c.email
        )
      ) as details_json
    FROM public.${sourceTable} t
    ${userJoinClause}
    ${responsibleJoinClause}
    CROSS JOIN (SELECT * FROM public.clinic LIMIT 1) c
    ${whereSql}
  `;

  results.push({
    json: { ...rule, dynamicQuery },
  });
}

return results;

// Las alertas creadas se leen de "Create alert instance" (ultima corrida = esta
// iteracion del loop), no de $input: aqui llegan filas de "Update rule next
// execution" o la respuesta del sub-workflow de WhatsApp, que no son alertas.
// Se filtra por rule_id para no contar las de una iteracion anterior cuando
// esta regla no genero resultados.
const ruleId = String($('Loop Over Results').first().json.id);
let created = [];
try {
  created = $('Create alert instance').all()
    .map((item) => item.json)
    .filter((a) => a && a.id != null && String(a.rule_id) === ruleId);
} catch (e) {
  created = [];
}

// Emails enviados en esta iteracion: resultados de "Send Alert Email" que
// corresponden a alertas de esta regla (el nodo conserva datos de iteraciones
// anteriores si esta vez no se ejecuto).
const createdIds = new Set(created.map((a) => String(a.id)));
let emailsSent = 0;
try {
  emailsSent = $('Send Alert Email').all()
    .filter((item) => item.json?.success === true && createdIds.has(String(item.json.alert_instance_id)))
    .length;
} catch (e) {
  emailsSent = 0;
}

return {
  success: true,
  execution_log: created.length ? created : [{}],
  emails_sent: emailsSent
};

// "Send Alert WhatsApp" devuelve el resultado del sub-workflow, no las alertas.
// Se recuperan las alertas creadas en esta iteracion para evaluar el envio por email.
return $('Create alert instance').all().map((item) => ({ json: item.json }));
